const r = await tools.exec_command({
  cmd: "wc -l /workspace/public/query.md /workspace/public/business-conversations.md /workspace/public/prd-schema.md && sed -n '1,240p' /workspace/public/query.md && sed -n '1,280p' /workspace/public/business-conversations.md && sed -n '1,320p' /workspace/public/prd-schema.md",
  workdir: "/workspace",
  yield_time_ms: 10000,
  max_output_tokens: 30000
});
text(r.output);

const cmds = [
  ["saleor", "git rev-parse HEAD && git status --short && find . -name AGENTS.md -print", "/workspace/repos/saleor"],
  ["dashboard", "git rev-parse HEAD && git status --short && find . -name AGENTS.md -print", "/workspace/repos/saleor-dashboard"],
  ["saleor-top", "find . -maxdepth 2 -type d | sort | sed -n '1,180p'", "/workspace/repos/saleor"],
  ["dash-top", "find . -maxdepth 2 -type d | sort | sed -n '1,180p'", "/workspace/repos/saleor-dashboard"]
];
const out = await Promise.all(cmds.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms: 10000, max_output_tokens: 12000});
  return `## ${name}\n${r.output}`;
}));
out.forEach(text);

const cmds = [
  ["saleor-root", "ls -la | sed -n '1,140p'; find . -name AGENTS.md -print", "/workspace/repos/saleor"],
  ["dash-root", "ls -la | sed -n '1,140p'; find . -name AGENTS.md -print", "/workspace/repos/saleor-dashboard"],
  ["commit-markers", "find /workspace/repos/saleor /workspace/repos/saleor-dashboard -maxdepth 2 -type f \\( -iname '*commit*' -o -iname '*version*' -o -name '.git_archival.txt' \\) -print | sort", "/workspace"]
];
const out = await Promise.all(cmds.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms: 10000, max_output_tokens: 12000});
  return `## ${name}\n${r.output}`;
}));
out.forEach(text);

const cmds = [
  ["saleor-agents", "sed -n '1,220p' AGENTS.md", "/workspace/repos/saleor"],
  ["dash-agents", "sed -n '1,260p' AGENTS.md", "/workspace/repos/saleor-dashboard"]
];
const out = await Promise.all(cmds.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms: 10000, max_output_tokens: 20000});
  return `## ${name}\n${r.output}`;
}));
out.forEach(text);

const searches = [
  ["shop-settings", "rg -n --glob '*.py' 'class Shop|ShopSettings|company_address|default_mail_sender|metadata|private_metadata|shopSettingsUpdate|shopAddressUpdate' saleor/site saleor/graphql | head -n 260", "/workspace/repos/saleor"],
  ["editor-image-search", "rg -n --glob '*.py' 'EditorJS|editorjs|structured|description_plaintext|sanitize|external.*image|fetch.*image|urlopen|requests\\.(get|head)|update_search|search_vector' saleor | head -n 360", "/workspace/repos/saleor"],
  ["stock-shipping", "rg -n --glob '*.py' 'shipping_zone|warehouse.*channel|channel.*warehouse|allocation_strategy|stock.*channel|external.*shipping|shipping.*cache|filter_shipping|excluded_shipping|checkout_filter_shipping' saleor/channel saleor/warehouse saleor/shipping saleor/checkout saleor/order saleor/webhook saleor/graphql | head -n 400", "/workspace/repos/saleor"],
  ["digital", "rg -n --glob '*.py' 'DigitalContent|digital_content|digitalContent|downloadUrl|digital content' saleor | head -n 360", "/workspace/repos/saleor"],
  ["gift-transaction", "rg -n --glob '*.py' 'TransactionItem|TransactionEvent|gift_card|GiftCard|gift card|HANDLE_PAYMENTS|MANAGE_GIFT_CARD' saleor/payment saleor/giftcard saleor/checkout saleor/order saleor/graphql | head -n 480", "/workspace/repos/saleor"],
  ["auth-plugin", "rg -n --glob '*.py' 'password.*policy|CUSTOMERS_ONLY|PASSWORD|OpenIDConnect|DummyCreditCard|Braintree|Razorpay|Dummy' saleor | head -n 420", "/workspace/repos/saleor"],
  ["app-webhook", "rg -n --glob '*.py' 'AppExtension|Mount|mount|circuit|observability|disabled.*webhook|WebhookEvent|subscription_query|sync_events|EventType' saleor/app saleor/webhook saleor/graphql | head -n 480", "/workspace/repos/saleor"]
];
const out = await Promise.all(searches.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms: 10000, max_output_tokens: 30000});
  return `## ${name}\n${r.output}`;
}));
out.forEach(text);

const searches = [
  ["schema-core", "rg -n '^  (shop|shopSettingsUpdate|shopAddressUpdate|transaction|transactions|digitalContent|digitalContents|digitalContentCreate|digitalContentUpdate|digitalContentDelete|digitalContentUrlCreate|channelUpdate|webhookCreate|webhookUpdate|appExtensions|externalAuthenticationUrl|externalObtainAccessTokens|tokenCreate|requestPasswordReset|setPassword)' schema.graphql", "/workspace/repos/saleor-dashboard"],
  ["schema-types", "rg -n '^enum AppExtensionMountEnum|^enum WebhookEventTypeAsyncEnum|^type TransactionItem|^type DigitalContent|^type Shop|^input ShopSettingsInput|^input ChannelUpdateInput|^type Channel|^type AppExtension|^type Webhook|^type WebhookDelivery' schema.graphql", "/workspace/repos/saleor-dashboard"],
  ["models-core", "rg -n --glob '!**/tests/**' --glob '*.py' '^class (SiteSettings|Channel|DigitalContent|DigitalContentUrl|TransactionItem|TransactionEvent|GiftCard|GiftCardEvent|AppExtension|Webhook|EventDelivery|EventPayload)' saleor", "/workspace/repos/saleor"],
  ["dash-routes", "rg -n --glob '!**/*.generated.ts' --glob '*.{ts,tsx}' 'digitalContent|DigitalContent|TransactionItem|transactionList|siteSettings|shopSettings|companyAddress|AppExtension|extension.*mount|observability|circuit|gift card|GiftCard' src | head -n 500", "/workspace/repos/saleor-dashboard"]
];
const out = await Promise.all(searches.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms: 10000, max_output_tokens: 24000});
  return `## ${name}\n${r.output}`;
}));
out.forEach(text);

