  ["giftcard-flow-symbols", "rg -n --glob '!**/tests/**' --glob '*.py' 'gift_card|GiftCard' saleor/checkout saleor/order saleor/payment | head -n 440", "/workspace/repos/saleor"],
  ["transaction-api", "sed -n '1,250p' saleor/graphql/payment/schema.py; sed -n '1,260p' saleor/payment/models.py; sed -n '500,720p' saleor/graphql/payment/types.py", "/workspace/repos/saleor"],
  ["transaction-schema", "sed -n '645,682p' schema.graphql; sed -n '11010,11210p' schema.graphql; rg -n '^input TransactionFilterInput|^input TransactionWhereInput|^enum TransactionSortField|TransactionSortingInput' schema.graphql", "/workspace/repos/saleor-dashboard"],
  ["dash-transaction-nongen", "rg -l --glob '!**/*.generated.ts' --glob '*.{ts,tsx}' 'TransactionItem|transactionCreate|transactionUpdate|transactionRequest|transactionEvent' src | sort | head -n 240", "/workspace/repos/saleor-dashboard"]
];
const out = await Promise.all(cmds.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms: 10000, max_output_tokens: 30000});
  return `## ${name}\n${r.output}`;
}));
out.forEach(text);

