const cmds = [
  ["desired-events", "rg -n 'SHOP_|TRANSACTION_|ATTRIBUTE_|CATEGORY_|MENU_|MENU_ITEM|PAGE_|PAGE_TYPE|PRODUCT_TYPE|SHIPPING_METHOD' saleor/webhook/event_types.py | head -n 360", "/workspace/repos/saleor"],
  ["subscription-modes", "rg -n --glob '!**/tests/**' 'subscription_query|Subscription|payload.*query|query.*required|event_type.*subscription' saleor/graphql/webhook saleor/webhook saleor/app | head -n 420", "/workspace/repos/saleor"],
  ["metadata-mutations", "rg -n --glob '!**/tests/**' --glob '*.py' 'metadata_updated|METADATA_UPDATED|UpdateMetadata|DeleteMetadata|update_metadata|delete_metadata' saleor/graphql/meta saleor/webhook saleor/plugins/manager.py | head -n 500", "/workspace/repos/saleor"],
  ["event-delivery-ui", "rg -n --glob '!**/*.generated.ts' --glob '*.{ts,tsx}' 'eventDeliver|observability|delivery.*status|webhook.*status|failed.*webhook|webhook.*failed|circuit' src/apps src | head -n 500", "/workspace/repos/saleor-dashboard"],
  ["manifest-ui", "rg -n --glob '!**/*.generated.ts' --glob '*.{ts,tsx}' 'subscriptionQuery|syncEvents|asyncEvents|WebhookEventType|webhookCreate|webhookUpdate' src/apps src | head -n 500", "/workspace/repos/saleor-dashboard"]
];
const out = await Promise.all(cmds.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms: 10000, max_output_tokens: 30000});
  return `## ${name}\n${r.output}`;
}));
out.forEach(text);

