const cmds = [
  ["breaker", "rg -n --glob '!**/tests/**' --glob '*.py' 'reenable|Reenable|disable.*sync|sync.*disable|observability|circuit' saleor/app saleor/graphql/app saleor/webhook saleor/plugins/webhook | head -n 480", "/workspace/repos/saleor"],
  ["app-model", "sed -n '1,180p' saleor/app/models.py; rg -n 'app_reenable_sync_webhooks|ReenableSync|sync_webhooks' saleor/graphql/app -g '*.py'", "/workspace/repos/saleor"],
  ["dash-breaker", "rg -n --glob '!**/*.generated.ts' --glob '*.{ts,tsx}' 'reenable|Reenable|syncWebhooks|sync webhook|observability|circuit' src/extensions src | head -n 440", "/workspace/repos/saleor-dashboard"],
  ["event-model-retry", "sed -n '150,290p' saleor/core/models.py; sed -n '1,180p' saleor/graphql/webhook/mutations/event_delivery_retry.py; rg -n 'max_retries|retry_backoff|EventDeliveryStatus.FAILED|event_delivery_retry' saleor/webhook/transport/asynchronous saleor/settings.py | head -n 320", "/workspace/repos/saleor"]
];
const out = await Promise.all(cmds.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms: 10000, max_output_tokens: 28000});
  return `## ${name}\n${r.output}`;
}));
out.forEach(text);

