    gift_cards = GiftCard.objects.filter(
        Q(used_by_email__in=emails)
        | Q(created_by_email__in=emails)
        | Q(used_by__in=users)
        | Q(created_by__in=users)
    )
    mark_gift_cards_search_index_as_dirty(gift_cards)


